WITH enriched AS (SELECT *, AVG(budget) OVER (ORDER BY budget ASC, id ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS budget_avg_6_prior, ROW_NUMBER() OVER (ORDER BY budget ASC, id ASC) AS row_seq, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget DESC, id ASC) AS row_seq_2 FROM departments), enriched_departments AS (SELECT id, dept_name, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget DESC, id ASC) AS row_seq_3, SUM(budget) OVER (PARTITION BY location ORDER BY budget ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget, NTILE(4) OVER (PARTITION BY location ORDER BY budget ASC, id ASC) AS budget_bucket FROM enriched), deduped AS (SELECT * FROM enriched_departments QUALIFY ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY cumulative_budget DESC NULLS LAST, id ASC) = 1), latest AS (SELECT id, dept_name, row_seq_3, budget_bucket FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY cumulative_budget ASC, id ASC) AS rn FROM deduped) ranked WHERE rn = 1) SELECT id, dept_name, row_seq_3 FROM latest ORDER BY id DESC NULLS FIRST, dept_name ASC LIMIT 10
